import{annotate}from"./rough-notation.js";function annotateOnFocus(o,t){for(const e of["mouseover","focus"])o.addEventListener(e,(()=>{t.show()}));for(const e of["mouseout","blur"])o.addEventListener(e,(()=>{t.hide()}))}const links=document.querySelectorAll("a"),linkAnnotateArray=[];links.forEach(((o,t)=>{linkAnnotateArray.push(annotate(o,{type:"highlight",color:"rgba(253, 166, 166, 0.3)",padding:15})),annotateOnFocus(o,linkAnnotateArray[t])}));const pictures=document.querySelectorAll(".img-box"),captionAnnotateArray=[];pictures.forEach(((o,t)=>{const e=o.querySelector(".caption");window.matchMedia("(prefers-color-scheme: dark)").matches?captionAnnotateArray.push(annotate(e,{type:"bracket",color:"#fff",strokeWidth:4,padding:[10,10],brackets:["left","right"]})):captionAnnotateArray.push(annotate(e,{type:"bracket",color:"#000",strokeWidth:4,padding:[10,10],brackets:["left","right"]})),annotateOnFocus(o,captionAnnotateArray[t])})),document.onkeydown=function(o){"Escape"===o.key&&document.querySelector(".modal-toggle:checked ~ .modal .modal-close")&&document.querySelector(".modal-toggle:checked ~ .modal .modal-close").click()};